using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using SupermarketCatalog.Data;using SupermarketCatalog.Models;namespace SupermarketCatalog.Pages.Admin;public class NewModel(AppDbContext db):PageModel{[BindProperty]public Deal Deal{get;set;}=new(){ExpiresAt=DateTime.UtcNow.AddDays(7)};public async Task<IActionResult> OnPostAsync(){Deal.StoreId=1;db.Deals.Add(Deal);await db.SaveChangesAsync();return RedirectToPage("Index");}}